import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadinbench.Application;
import com.vaadinbench.ui.ItemView;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

@SpringBootTest(classes = Application.class)
class ItemViewTest extends SpringBrowserlessTest {

    @Test
    void addAppendsItemClearsFieldAndUpdatesCount() {
        navigate(ItemView.class);
        TextField field = $(TextField.class).single();
        test(field).setValue("Apple");
        test($(Button.class).withText("Add").single()).click();

        assertEquals("Items: 1", $(Span.class).single().getText());
        assertEquals("Apple", $(ListItem.class).single().getText());
        assertEquals("", field.getValue());
        assertFalse(field.isInvalid());
    }

    @Test
    void blankAddIsRejectedAndMarksFieldInvalid() {
        navigate(ItemView.class);
        TextField field = $(TextField.class).single();
        test(field).setValue("   ");
        test($(Button.class).withText("Add").single()).click();

        assertEquals("Items: 0", $(Span.class).single().getText());
        assertTrue($(ListItem.class).all().isEmpty());
        assertTrue(field.isInvalid());
    }

    @Test
    void duplicatesAreAllowedAndClearRemovesEverything() {
        navigate(ItemView.class);
        TextField field = $(TextField.class).single();
        Button add = $(Button.class).withText("Add").single();
        test(field).setValue("Same");
        test(add).click();
        test(field).setValue("Same");
        test(add).click();
        assertEquals("Items: 2", $(Span.class).single().getText());

        test($(Button.class).withText("Clear").single()).click();
        assertEquals("Items: 0", $(Span.class).single().getText());
        assertTrue($(ListItem.class).all().isEmpty());

        test(field).setValue("Again");
        test(add).click();
        assertEquals("Items: 1", $(Span.class).single().getText());
    }

}
